// Generates the OpenUI Lang system prompt for the "Ask Verytas" copilot from the
// component library, at build time. Keeping it as a checked-in text file means
// the exact instructions sent to the model are reviewable in git, and the chat
// route never has to import client-side React components on the server.
import { writeFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const { openuiLibrary, openuiPromptOptions } = require("@openuidev/react-ui");

// House style forbids em dashes anywhere in the repo, generated files included;
// a plain hyphen reads the same to the model.
const prompt = openuiLibrary.prompt(openuiPromptOptions).replaceAll("\u2014", "-");
// A template literal (not JSON) keeps the prompt human-readable in diffs.
const escaped = prompt.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
const out = new URL("../src/generated/openui-prompt.ts", import.meta.url);
writeFileSync(out, `// Generated by scripts/gen-openui-prompt.mjs. Do not edit by hand.\nexport const OPENUI_PROMPT = \`${escaped}\`;\n`);
console.log(`wrote ${prompt.length} chars to src/generated/openui-prompt.ts`);
